/* Process entry point, TLS directory, stack probe and argv/environ setup for
 * the Windows backend.  Replaces the MSVC CRT (mainCRTStartup, tlssup.c,
 * chkstk.asm), so no CRT/SDK libraries are needed. */
#include "../pal.h"
#include "win.h"
#include <stdint.h>

/* The compiler may emit references to _fltused when floating point is used. */
int _fltused = 1;

/* ---------------------------------------------------------------------- */
/* Stack probe (__chkstk): touches every page of a large frame             */
/* ---------------------------------------------------------------------- */
#if defined(__x86_64__)
__asm__(
    ".text\n"
    ".globl __chkstk\n"
    "__chkstk:\n"
    "  push %rcx\n"
    "  push %rax\n"
    "  cmp $0x1000, %rax\n"
    "  lea 24(%rsp), %rcx\n"
    "  jb 2f\n"
    "1:\n"
    "  sub $0x1000, %rcx\n"
    "  test %rcx, (%rcx)\n"
    "  sub $0x1000, %rax\n"
    "  cmp $0x1000, %rax\n"
    "  ja 1b\n"
    "2:\n"
    "  sub %rax, %rcx\n"
    "  test %rcx, (%rcx)\n"
    "  pop %rax\n"
    "  pop %rcx\n"
    "  ret\n");
#elif defined(__aarch64__)
__asm__(
    ".text\n"
    ".globl __chkstk\n"
    "__chkstk:\n"
    "  lsl x16, x15, #4\n"
    "  mov x17, sp\n"
    "1:\n"
    "  sub x17, x17, #4096\n"
    "  subs x16, x16, #4096\n"
    "  ldr xzr, [x17]\n"
    "  b.gt 1b\n"
    "  ret\n");
#endif

/* ---------------------------------------------------------------------- */
/* PE TLS directory so that _Thread_local works without the CRT            */
/* ---------------------------------------------------------------------- */

typedef struct {
    uint64_t StartAddressOfRawData, EndAddressOfRawData, AddressOfIndex,
             AddressOfCallBacks;
    uint32_t SizeOfZeroFill, Characteristics;
} TLS_DIRECTORY64;

#pragma clang diagnostic ignored "-Wignored-attributes"
__attribute__((section(".tls")))      char _tls_start = 0;
__attribute__((section(".tls$ZZZ")))  char _tls_end = 0;
unsigned _tls_index = 0;
#ifdef _LIBC23_HAS_THREADS
/* Called under the loader lock before the exiting thread's TLS is released.
 * Portable cleanup is idempotent when thrd_exit already ran destructors. */
static void tls_callback(void *module, DWORD reason, void *reserved) {
    (void)module; (void)reserved;
    /* Do not run user destructors during process termination: other threads
     * may have been stopped while holding locks needed by the destructors. */
    if (reason == 3) /* DLL_THREAD_DETACH */
        __libc_tss_run_dtors();
}
static void (*const tls_callbacks[])(void *, DWORD, void *) = { tls_callback, 0 };
#define TLS_CALLBACKS_ADDRESS ((uint64_t)(uintptr_t)tls_callbacks)
#else
#define TLS_CALLBACKS_ADDRESS 0
#endif
__attribute__((used, section(".rdata$T")))
const TLS_DIRECTORY64 _tls_used = {
    (uint64_t)(uintptr_t)&_tls_start, (uint64_t)(uintptr_t)&_tls_end,
    (uint64_t)(uintptr_t)&_tls_index, TLS_CALLBACKS_ADDRESS, 0, 0
};

/* Import libraries needed by this backend (generated by build.py). */
#pragma comment(lib, "kernel32.lib")
#pragma comment(lib, "synch.lib")
#pragma comment(lib, "bcryptprimitives.lib")

/* ---------------------------------------------------------------------- */
/* argv / environ                                                          */
/* ---------------------------------------------------------------------- */

static size_t round_page(size_t n) {
    size_t ps = pal_page_size();
    return (n + ps - 1) / ps * ps;
}

/* Split the UTF-8 command line using the Microsoft rules (same as
 * CommandLineToArgvW/UCRT). Works in place on `cl`; fills argv. */
static int parse_cmdline(char *cl, char **argv) {
    int argc = 0;
    char *p = cl, *out = cl;
    /* program name: no escape processing */
    argv[argc++] = out;
    if (*p == '"') {
        p++;
        while (*p && *p != '"') *out++ = *p++;
        if (*p == '"') p++;
    } else {
        while (*p && *p != ' ' && *p != '\t') *out++ = *p++;
    }
    /* p and out coincide for an unquoted program name.  Advance past the
     * separator before writing the terminator, or it would hide all args. */
    while (*p == ' ' || *p == '\t') p++;
    *out++ = 0;
    for (;;) {
        while (*p == ' ' || *p == '\t') p++;
        if (!*p) break;
        argv[argc++] = out;
        int inq = 0;
        for (;;) {
            unsigned bs = 0;
            while (*p == '\\') { bs++; p++; }
            if (*p == '"') {
                for (unsigned i = 0; i < bs / 2; i++) *out++ = '\\';
                if (bs & 1) { *out++ = '"'; p++; }
                else if (inq && p[1] == '"') { *out++ = '"'; p += 2; }
                else { inq = !inq; p++; }
            } else {
                for (unsigned i = 0; i < bs; i++) *out++ = '\\';
                if (!*p || (!inq && (*p == ' ' || *p == '\t'))) break;
                *out++ = *p++;
            }
        }
        if (*p) p++;
        *out++ = 0;
    }
    argv[argc] = 0;
    return argc;
}

void __libc_mainCRTStartup(void) {
    /* --- command line --- */
    LPWSTR wcl = GetCommandLineW();
    int n = WideCharToMultiByte(CP_UTF8, 0, wcl, -1, NULL, 0, NULL, NULL);
    if (n <= 0) pal_exit(127);
    size_t cap = (size_t)n + (size_t)n / 2 + 64;
    size_t bytes = round_page(cap + (size_t)(n / 2 + 4) * sizeof(char *) + 16);
    char *mem = pal_mem_map(bytes);
    if (!mem) pal_exit(127);
    char *cl = mem;
    char **argv = (char **)(mem + ((cap + 15) & ~(size_t)15));
    if (!WideCharToMultiByte(CP_UTF8, 0, wcl, -1, cl, n, NULL, NULL)) pal_exit(127);
    int argc = parse_cmdline(cl, argv);

    /* --- environment --- */
    LPWSTR wenv = GetEnvironmentStringsW();
    static char *empty_env[] = { NULL };
    char **envp = empty_env;
    if (wenv) {
        int wlen = 0;
        int count = 0;
        while (wenv[wlen]) { while (wenv[wlen]) wlen++; wlen++; count++; }
        wlen++; /* final NUL */
        int u8 = WideCharToMultiByte(CP_UTF8, 0, wenv, wlen, NULL, 0, NULL, NULL);
        if (u8 <= 0) pal_exit(127);
        size_t ebytes = round_page((size_t)u8 + (size_t)(count + 1) * sizeof(char *) + 16);
        char *emem = pal_mem_map(ebytes);
        if (emem) {
            char *buf = emem;
            envp = (char **)(emem + (((size_t)u8 + 15) & ~(size_t)15));
            if (!WideCharToMultiByte(CP_UTF8, 0, wenv, wlen, buf, u8, NULL, NULL)) pal_exit(127);
            int k = 0;
            for (char *s = buf; *s;) {
                if (*s != '=') envp[k++] = s; /* skip hidden "=C:=..." entries */
                while (*s) s++;
                s++;
            }
            envp[k] = NULL;
        }
        FreeEnvironmentStringsW(wenv);
    }
    pal_environ = envp;

    /* --- console: UTF-8 and VT sequences --- */
    DWORD mode;
    HANDLE ho = GetStdHandle(STD_OUTPUT_HANDLE), he = GetStdHandle(STD_ERROR_HANDLE),
           hi = GetStdHandle(STD_INPUT_HANDLE);
    if (hi && hi != INVALID_HANDLE_VALUE && GetConsoleMode(hi, &mode)) SetConsoleCP(CP_UTF8);
    if (ho && ho != INVALID_HANDLE_VALUE && GetConsoleMode(ho, &mode)) {
        SetConsoleOutputCP(CP_UTF8);
        SetConsoleMode(ho, mode | ENABLE_PROCESSED_OUTPUT | ENABLE_VIRTUAL_TERMINAL_PROCESSING);
    }
    if (he && he != INVALID_HANDLE_VALUE && GetConsoleMode(he, &mode))
        SetConsoleMode(he, mode | ENABLE_PROCESSED_OUTPUT | ENABLE_VIRTUAL_TERMINAL_PROCESSING);

    __libc_start_main(argc, argv, envp);
}
